function rootToLeafRoutes(root: TreeNode | null): string[] {
  const out: string[] = [];
  const dfs = (n: TreeNode, route: string): void => {
    const here = route ? route + "->" + n.val : String(n.val);
    if (!n.left && !n.right) { out.push(here); return; }
    if (n.left) dfs(n.left, here);
    if (n.right) dfs(n.right, here);
  };
  if (root) dfs(root, "");
  return out;
}

