function rootToLeafRoutes(root: TreeNode | null): string[] {
  const out: string[] = [];
  if (!root) return out;
  const stack: [TreeNode, number[]][] = [[root, [root.val]]];
  while (stack.length) {
    const [n, vals] = stack.pop()!;
    if (!n.left && !n.right) out.push(vals.join("->"));
    if (n.right) stack.push([n.right, [...vals, n.right.val]]);
    if (n.left) stack.push([n.left, [...vals, n.left.val]]);
  }
  return out;
}

