class Solution:
    def rootToLeafRoutes(self, root: Optional[TreeNode]) -> List[str]:
        if not root:
            return []
        out, stack = [], [(root, [root.val])]
        while stack:
            n, vals = stack.pop()
            if not n.left and not n.right:
                out.append("->".join(map(str, vals)))
            for child in (n.right, n.left):
                if child:
                    stack.append((child, vals + [child.val]))
        return out

